; ============================================================================
; RST VECTORS AND THE FIXED JUMP TABLE
; ============================================================================

;------------------------------------------------------------------------------
; 0000H - RST vectors and the fixed jump table (0000H-0320H)
; Page 0 of bank 0 is never switched out, so everything here is callable from
; any bank with a plain CALL.  The table entries are 3 bytes each, of three kinds:
;   JP   nnnn        routine lives in this ROM
;   RST 18H / DW nn  BANKJP: tail-jump into another bank, the bank being implied
;                    by the target address (0000-3FFF bank 0, 4000-7FFF bank 3,
;                    8000-BFFF bank 6, C000-FFFF bank 0 upper half at nn-8000H).
;                    The previous banking is restored when the routine returns.
;   CALL F09D/A2/A7  RAM-relocatable hook (display/print/keyboard): the RAM stub
;                    works out which entry was called from the return address.
; Names are those of the Systemhandbuch, Anhang 8.  The Z-80 RST 00H..38H slots
; are interleaved with the table; the bytes between them are unused filler.
;------------------------------------------------------------------------------
RESET:
	nop                             ; 0000  00           RST 00H: cold/warm reset
	di                              ; 0001  f3
	jp RESETGO                      ; 0002  c31703       -> reset / power-on entry
APO:
	jp APO_I                        ; 0005  c34a0c       auto power-off (resumable)
RST08:
	jp RST08V                       ; 0008  c3cef0       RST 08H: user vector in RAM (RET when unused)
CRSRPOS_IMPL:
	ld de,(CRSRY)                   ; 000B  ed5b5ff0     cursor position -> D=y, E=x (used by 0118H CRSRPOS)
	ret                             ; 000F  c9
RST10:
	ret                             ; 0010  c9           RST 10H: unused, returns at once
	defb 0FH,0D4H,17H,12H           ; 0011  0fd41712     unused filler
EXROMCAL:
	rst 18H                         ; 0015  df           BANKJP call entry +L of every ROM module (A=function, E/D=bitmaps)
	defw CALLMODS                   ; 0016  3509         -> bank 0: 0935
BANKJP:
	jp BANKJP_I                     ; 0018  c3760b       RST 18H: BANKJP, 2-byte target follows the RST
JPHLA:
	rst 18H                         ; 001B  df           BANKJP jump to HL in bank A
	defw JPHLA_I                    ; 001C  6209         -> bank 0: 0962
	defb 0F0H,07H                   ; 001E  f007         unused filler
BANKCAL:
	jp BANKCAL_I                    ; 0020  c39309       RST 20H: BANKCAL, bank byte + 2-byte target follow the RST
CHKMSG:
	jp CHKMSG_T                     ; 0023  c3a138       check / error message output
	defb 70H,07H                    ; 0026  7007         unused filler
RST28:
	jp RST28V                       ; 0028  c3d1f0       RST 28H: user vector in RAM
APOTST:
	rst 18H                         ; 002B  df           BANKJP
	defw 407EH                      ; 002C  7e40         -> bank 3: 407E T_APOTST
	defb 0FDH,00H                   ; 002E  fd00         unused filler
RST30:
	jp RST30V                       ; 0030  c3d4f0       RST 30H: user vector in RAM
	defb 1FH,5EH                    ; 0033  1f5e         unused filler
POCLOS:
	jp POCLOS_I                     ; 0035  c3f910       close all files + power off
RST38:
	jp RST38V                       ; 0038  c3d7f0       RST 38H: user vector in RAM
SSLOTMP:
	rst 18H                         ; 003B  df           BANKJP
	defw 4078H                      ; 003C  7840         -> bank 3: 4078 T_SSLOTMP
SETPRSLOT:
	rst 18H                         ; 003E  df           BANKJP
	defw 407BH                      ; 003F  7b40         -> bank 3: 407B T_SETPRSLOT
WAKES:
	rst 18H                         ; 0041  df           BANKJP
	defw 40BAH                      ; 0042  ba40         -> bank 3: 40BA T_WAKES
WAKESLET:
	rst 18H                         ; 0044  df           BANKJP
	defw 4081H                      ; 0045  8140         -> bank 3: 4081 T_WAKESLET
CALLCMD:
	rst 18H                         ; 0047  df           BANKJP
	defw 4087H                      ; 0048  8740         -> bank 3: 4087 T_CALLCMD
OUTCMD:
	rst 18H                         ; 004A  df           BANKJP
	defw 408AH                      ; 004B  8a40         -> bank 3: 408A T_OUTCMD
POKECMD:
	rst 18H                         ; 004D  df           BANKJP
	defw 408DH                      ; 004E  8d40         -> bank 3: 408D T_POKECMD
JAPAN0050:
	rst 18H                         ; 0050  df           BANKJP
	defw 4090H                      ; 0051  9040         -> bank 3: 4090 T_JAPAN0050
JAPAN0053:
	rst 18H                         ; 0053  df           BANKJP
	defw 4093H                      ; 0054  9340         -> bank 3: 4093 T_JAPAN0053
