; IM2 interrupt vector: I = 03H, port 39H = 15H, so the vector word is at 0315H,
; immediately below the reset code it follows (TRM: vector = entry address - 2).
; OLD revision: the table ends here; the NEW one has four more entries (RSTEXT1-4,
; 0315H-031EH) and the vector at 0321H.
IM2VEC:
	defw INTHND                     ; 0315  1009         IM2 vector table (I=03H, port 39H=15H) -> interrupt handler



; ============================================================================
; RESET / POWER-ON
; ============================================================================

;------------------------------------------------------------------------------
; 0317H - Reset / power-on entry (from 0002H)
; Every power-on is a Z-80 reset (the sub-CPU holds RSTIN# low for 30 ms).
; 1. LCD clock on, SP = FA38H, LCD display off, settle, init the TC8576 CPC.
; 2. Ask the sub-CPU for the reset cause (timer IOCS 15H), re-order its bits
;    into RSTCAUSE (FA1BH): b0 ALL RESET, b1 RESET switch, b2 external reset,
;    b4 ON key, b5 external power-on, b6 WAKE$(0), b7 WAKE$(1).
; 3. For a power-on, an A5H x4 signature at ZZ (FA08H) means "auto power-off,
;    resume": SP is reloaded from SAVESP and the handler at APONBK/APONAD
;    (default bank 3, 407EH) is called; on success execution continues in the
;    auto-power-off routine at 0BBDH, i.e. the program resumes.
; 4. Otherwise a normal start: IM 2, work-area init (ALL RESET: full clear),
;    slot/module detection, CPU hand-shake with the LH-5803, ROM module scan,
;    calls into every module, timer/COM init, and finally the boot search which
;    ends in the boot vector BOOTBK/BOOTAD (default 0C04H, BASIC).
;------------------------------------------------------------------------------
RESETGO:
	ld a,10H                        ; 0317  3e10         b4 = LCD processor clock (CK0) on
	out (P_CGC),a                   ; 0319  d337
	ld sp,BASSTK                    ; 031B  3138fa
	ld a,3EH                        ; 031E  3e3e         HD61202 command 3EH = display OFF
	call LCDWAIT                    ; 0320  cdea08
	out (P_LCD1C),a                 ; 0323  d350
	call DELAY30K                   ; 0325  cd6f07
	call CPCINIT                    ; 0328  cdb007
	call WAITONUP                   ; 032B  cd7807
	ld hl,SYSFLG                    ; 032E  21b8f0
	res 0,(hl)                      ; 0331  cb86         sub-CPU commands paced to 64 Hz until probed
	ld a,04H                        ; 0333  3e04         04H: bank 3 = normal ROM, not the hidden 3b
	ld (PORT3D_M),a                 ; 0335  327df0
	out (P_ROMSEL),a                ; 0338  d33d
	ld c,15H                        ; 033A  0e15         timer IOCS 15H: reset / power-on cause -> A
	call TIMER                      ; 033C  cdd501

; Reorder the cause bits: answer b7..b5 -> C b2..b0 (b5 ALL RESET -> b0),
; answer b4 dropped, answer b3..b0 -> C b4..b7.
	ld c,00H                        ; 033F  0e00
	ld b,03H                        ; 0341  0603
L0343:
	rlca                            ; 0343  07
	rr c                            ; 0344  cb19
	djnz L0343                      ; 0346  10fb
	rlca                            ; 0348  07
	ld b,04H                        ; 0349  0604
L034B:
	rlca                            ; 034B  07
	rr c                            ; 034C  cb19
	djnz L034B                      ; 034E  10fb
	ld a,c                          ; 0350  79
	bit 3,a                         ; 0351  cb5f
	jr z,L0357                      ; 0353  2802
	ld a,01H                        ; 0355  3e01         ALL RESET: RSTCAUSE = 01H exactly
L0357:
	and a                           ; 0357  a7
	jr nz,RSTSAVE                   ; 0358  2002
	ld a,10H                        ; 035A  3e10         no cause bits: treat as ON-key power-on (10H)



;------------------------------------------------------------------------------
; 035CH - Store the start cause in A and continue the boot
; Also entered from the power-off code.
;------------------------------------------------------------------------------
RSTSAVE:
	ld (RSTCAUSE),a                 ; 035C  321bfa
	cp 10H                          ; 035F  fe10         < 10H: a reset, not a power-on
	jr c,L0368                      ; 0361  3805
	call SIGCHK                     ; 0363  cdca08
	jr c,L0371                      ; 0366  3809         signature found: resume with the saved stack
L0368:
	call SIGCLR                     ; 0368  cde208
	ld hl,0F5FFH                    ; 036B  21fff5
	ld (SAVESP),hl                  ; 036E  22daf0
L0371:
	ld sp,(SAVESP)                  ; 0371  ed7bdaf0     SP = saved (resume) or F5FFH (normal start)

; Interrupt mode 2, vector table at 0315H (I = 03H, port 39H = 15H).
	ld hl,IM2VEC                    ; 0375  211503
	ld a,h                          ; 0378  7c
	ld i,a                          ; 0379  ed47
	ld a,l                          ; 037B  7d
	out (P_IVEC),a                  ; 037C  d339
	im 2                            ; 037E  ed5e
	call DELAY30K                   ; 0380  cd6f07
	call CPCINIT                    ; 0383  cdb007
	ld hl,SYSFLG                    ; 0386  21b8f0
	res 0,(hl)                      ; 0389  cb86
	ld hl,0FA21H                    ; 038B  2121fa       clear FA21H-FA24H (flags collected during boot)
	xor a                           ; 038E  af
	ld b,04H                        ; 038F  0604
L0391:
	ld (hl),a                       ; 0391  77
	inc hl                          ; 0392  23
	djnz L0391                      ; 0393  10fc
	call WAITONUP                   ; 0395  cd7807
	ld a,(RSTCAUSE)                 ; 0398  3a1bfa
	cp 10H                          ; 039B  fe10
	jr nc,L03AB                     ; 039D  300c         power-on (>= 10H): keep the work area
	cp 02H                          ; 039F  fe02
	jr nc,L03A8                     ; 03A1  3005         RESET switch / external reset: vectors only
	call ALLRESET                   ; 03A3  cdd106       ALL RESET: clear the whole work area
	jr L03AB                        ; 03A6  1803
L03A8:
	call VECINIT                    ; 03A8  cd3107
L03AB:
	ld c,25H                        ; 03AB  0e25         timer IOCS 25H: does the sub-CPU need 64 Hz pacing?
	call TIMER                      ; 03AD  cdd501
	ld hl,SYSFLG                    ; 03B0  21b8f0       -> SYSFLG b0 (1 = send commands unpaced)
	or (hl)                         ; 03B3  b6
	ld (hl),a                       ; 03B4  77

; LCD display start line = DSPLPTR, as HD61202 command C0H+line*8.
	ld a,(DSPLPTR)                  ; 03B5  3a5cf0
	add a,a                         ; 03B8  87
	add a,a                         ; 03B9  87
	add a,a                         ; 03BA  87
	or 0C0H                         ; 03BB  f6c0
	call LCDWAIT                    ; 03BD  cdea08
	out (P_LCD1C),a                 ; 03C0  d350
	xor a                           ; 03C2  af
	out (P_SLOT),a                  ; 03C3  d33c

; Probe the Slot 1 memory window (SLOTMAP = 0 meanwhile) to decide SLOTMAP:
; RAM/ROM at bank 0 B000H -> 1BH, else at A800H -> 1AH, else 5BH.
	ld d,00H                        ; 03C5  1600
	ld e,0B0H                       ; 03C7  1eb0
	call MEMORYCHK_I                ; 03C9  cd030a
	jr c,L03DD                      ; 03CC  380f
	ld e,0A8H                       ; 03CE  1ea8
	call MEMORYCHK_I                ; 03D0  cd030a
	jr c,L03D9                      ; 03D3  3804
	ld a,5BH                        ; 03D5  3e5b
	jr L03DF                        ; 03D7  1806
L03D9:
	ld a,1AH                        ; 03D9  3e1a
	jr L03DF                        ; 03DB  1802
L03DD:
	ld a,1BH                        ; 03DD  3e1b
L03DF:
	ld (SLOTMAPM),a                 ; 03DF  328df0
	out (P_SLOT),a                  ; 03E2  d33c

; Detect whether a Slot-2 I/O device answers at ports 60H-67H: save the 8
; values, write 05H..0CH, read back.  If all read back, restore them and flag
; FA24H.7 (device present => module configuration changed: signature cleared).
	ld bc,8060H                     ; 03E4  016080       B = 80H is on A8-A15 during IN (C); C = port 60H
	ld d,08H                        ; 03E7  1608
L03E9:
	in a,(c)                        ; 03E9  ed78
	push af                         ; 03EB  f5
	inc bc                          ; 03EC  03
	dec d                           ; 03ED  15
	jr nz,L03E9                     ; 03EE  20f9
	ld c,60H                        ; 03F0  0e60
	ld d,08H                        ; 03F2  1608
	ld a,05H                        ; 03F4  3e05
L03F6:
	out (c),a                       ; 03F6  ed79
	inc bc                          ; 03F8  03
	inc a                           ; 03F9  3c
	dec d                           ; 03FA  15
	jr nz,L03F6                     ; 03FB  20f9
	ld c,60H                        ; 03FD  0e60
	ld d,08H                        ; 03FF  1608
	ld e,05H                        ; 0401  1e05
L0403:
	in a,(c)                        ; 0403  ed78
	cp e                            ; 0405  bb
	jr nz,L0422                     ; 0406  201a
	inc bc                          ; 0408  03
	inc e                           ; 0409  1c
	dec d                           ; 040A  15
	jr nz,L0403                     ; 040B  20f6
	ld c,67H                        ; 040D  0e67
	ld d,08H                        ; 040F  1608
L0411:
	pop af                          ; 0411  f1
	out (c),a                       ; 0412  ed79
	dec bc                          ; 0414  0b
	dec d                           ; 0415  15
	jr nz,L0411                     ; 0416  20f9
	call SIGCLR                     ; 0418  cde208
	ld hl,0FA24H                    ; 041B  2124fa
	set 7,(hl)                      ; 041E  cbfe
	jr L0427                        ; 0420  1805
L0422:
	ld b,08H                        ; 0422  0608         no device: drop the 8 saved values
L0424:
	pop af                          ; 0424  f1
	djnz L0424                      ; 0425  10fd

; Remember the old module bitmaps (F0AE-F0B1H) in YY to detect configuration changes.
L0427:
	ld hl,(ROM4MAP)                 ; 0427  2aaef0
	ld (YY),hl                      ; 042A  2210fa
	ld hl,(0F0B0H)                  ; 042D  2ab0f0
	ld (0FA12H),hl                  ; 0430  2212fa
	ld a,08H                        ; 0433  3e08         interrupt mask: only b3 (LH-5803) enabled
	out (P_ZMSK),a                  ; 0435  d335
	ld a,40H                        ; 0437  3e40         LH-5803 call mode 40H: initialise the LH-5803 side
	ld (LHMODE),a                   ; 0439  3202f0
	call CALLH                      ; 043C  cdc601       the LH-5803 enables interrupts again on return
	di                              ; 043F  f3
	ld a,04H                        ; 0440  3e04
	ld (PORT3D_M),a                 ; 0442  327df0
	out (P_ROMSEL),a                ; 0445  d33d

; Scan banks 1-7 for ROM modules (ID 43H,16H) at 4000H and at 6000H.
	ld hl,4000H                     ; 0447  210040
	call SCANMODS                   ; 044A  cda908
	ld (ROM4MAP),a                  ; 044D  32aef0
	ld hl,6000H                     ; 0450  210060
	call SCANMODS                   ; 0453  cda908
	ld (ROM6MAP),a                  ; 0456  32aff0
	ld a,07H                        ; 0459  3e07         module function 7: reset
	ld l,02H                        ; 045B  2e02
	ld de,(ROM4MAP)                 ; 045D  ed5baef0
	call CALLMODS                   ; 0461  cd3509
	ld hl,(ROM4MAP)                 ; 0464  2aaef0
	ex de,hl                        ; 0467  eb
	ld hl,(YY)                      ; 0468  2a10fa       bitmaps changed: clear the signature
	and a                           ; 046B  a7
	sbc hl,de                       ; 046C  ed52
	call nz,SIGCLR                  ; 046E  c4e208
	ld hl,(0F0B0H)                  ; 0471  2ab0f0
	ex de,hl                        ; 0474  eb
	ld hl,(0FA12H)                  ; 0475  2a12fa
	and a                           ; 0478  a7
	sbc hl,de                       ; 0479  ed52
	call nz,SIGCLR                  ; 047B  c4e208
	ld c,01H                        ; 047E  0e01
	ld a,(ROM4MAP)                  ; 0480  3aaef0
	call S07EB                      ; 0483  cdeb07       bank 3 6BF0H: register the modules of the 4000H map
	ld a,(ROM6MAP)                  ; 0486  3aaff0
	call S07EB                      ; 0489  cdeb07       ... and of the 6000H map
	ld hl,(MODCFG1)                 ; 048C  2a23f1
	ld (YY),hl                      ; 048F  2210fa
	ld hl,(MODCFG2)                 ; 0492  2a25f1
	ld (0FA12H),hl                  ; 0495  2212fa
	call S0820                      ; 0498  cd2008       bank 3 6C0BH: rebuild the coded configuration
	ld hl,(YY)                      ; 049B  2a10fa
	ld de,(MODCFG1)                 ; 049E  ed5b23f1
	call S07CF                      ; 04A2  cdcf07       bank 3 6B13H: compare with the old one (flags a change)
	ld hl,(0FA12H)                  ; 04A5  2a12fa
	ld de,(MODCFG2)                 ; 04A8  ed5b25f1
	call S07CF                      ; 04AC  cdcf07

; Check for a JAPAN ROM (header 'M',3xH/4xH at bank 4, 8000H) -> D.0
	ld d,00H                        ; 04AF  1600
	call SELJROM                    ; 04B1  cd8107
	ld a,(8000H)                    ; 04B4  3a0080
	cp 44H                          ; 04B7  fe44
	jr nz,L04D9                     ; 04B9  201e
	ld a,(8001H)                    ; 04BB  3a0180
	cp 16H                          ; 04BE  fe16
	jr nz,L04D9                     ; 04C0  2017
	set 1,d                         ; 04C2  cbca
	jr L04D9                        ; 04C4  1813



;------------------------------------------------------------------------------
; 04C6H - Compare the operator on top of the evaluation stack (the NEW revision has this at 3EFCH)
;------------------------------------------------------------------------------
EVOPRCMP:
	jr nz,L04CF                     ; 04C6  2007
	call EVTOPOPR                   ; 04C8  cd0233
	and a                           ; 04CB  a7
	sbc hl,de                       ; 04CC  ed52
	ret z                           ; 04CE  c8
L04CF:
	ld a,0E8H                       ; 04CF  3ee8
	jp L31DD                        ; 04D1  c3dd31
	defb 00H                        ; 04D4  00           ?? '.'
	defb 00H,00H,00H,00H            ; 04D5  00000000

; F122H b0 = JAPAN ROM present; a change also invalidates the resume signature.
L04D9:
	ld a,(MODCFG)                   ; 04D9  3a22f1
	and 03H                         ; 04DC  e603
	cp d                            ; 04DE  ba
	call nz,SIGCLR                  ; 04DF  c4e208
	ld a,(MODCFG)                   ; 04E2  3a22f1
	and 0FCH                        ; 04E5  e6fc
	or d                            ; 04E7  b2
	ld (MODCFG),a                   ; 04E8  3222f1
	ld a,04H                        ; 04EB  3e04
	ld (PORT3D_M),a                 ; 04ED  327df0
	out (P_ROMSEL),a                ; 04F0  d33d
	xor a                           ; 04F2  af
	out (P_SUBDAT),a                ; 04F3  d333
	ld (TMRMSK),a                   ; 04F5  327ef0
	ld c,12H                        ; 04F8  0e12         timer IOCS 12H SRIRQ: read (and so clear) pending events
	call TIMER                      ; 04FA  cdd501
	xor a                           ; 04FD  af
	out (P_CL1),a                   ; 04FE  d336
	ld (BINTP1),a                   ; 0500  32d3f1
	ld (BINTP2),a                   ; 0503  32d4f1
	ld hl,BMODE                     ; 0506  21bcf1
	ld a,(hl)                       ; 0509  7e
	and 7FH                         ; 050A  e67f
	ld b,a                          ; 050C  47
	in a,(P_OPB)                    ; 050D  db1f         PB3 -> BMODE b7
	and 08H                         ; 050F  e608
	jr z,L0515                      ; 0511  2802
	set 7,b                         ; 0513  cbf8
L0515:
	ld (hl),b                       ; 0515  70
	ld hl,KEYWK2                    ; 0516  217af0
	res 0,(hl)                      ; 0519  cb86
	ld hl,0000H                     ; 051B  210000
	ld (CONTADR),hl                 ; 051E  22b9f0
	call SIGCHK                     ; 0521  cdca08       resume after auto power-off?
	jr nc,L0564                     ; 0524  303e

; Resume after auto power-off: re-initialise the peripherals with "power on
; after APO" (A = 2), then call the APO handler (default bank 3 407EH).  Any
; configuration change flagged in FA21H-FA24H forces a normal start instead.
	call BUZON                      ; 0526  cdc301
	ld a,02H                        ; 0529  3e02
	ld c,00H                        ; 052B  0e00         timer IOCS 00H SINIT
	call TIMER                      ; 052D  cdd501
	ld a,02H                        ; 0530  3e02
	ld c,00H                        ; 0532  0e00
	call COM                        ; 0534  cdd801       COM IOCS 00H init
	ld a,02H                        ; 0537  3e02
	ld de,(ROM4MAP)                 ; 0539  ed5baef0
	ld l,02H                        ; 053D  2e02
	call CALLMODS                   ; 053F  cd3509
	ld a,02H                        ; 0542  3e02
	call PAOFF_ENT                  ; 0544  cdc901
	ld hl,0FA21H                    ; 0547  2121fa
	ld a,(hl)                       ; 054A  7e
	inc hl                          ; 054B  23
	or (hl)                         ; 054C  b6
	inc hl                          ; 054D  23
	or (hl)                         ; 054E  b6
	inc hl                          ; 054F  23
	or (hl)                         ; 0550  b6
	jr nz,L0564                     ; 0551  2011         configuration changed: normal start
	ld a,(APONBK)                   ; 0553  3acbf0       BANKCALL APONBK:APONAD (A'/HL' = bank/address)
	ld hl,(APONAD)                  ; 0556  2accf0
	ex af,af'                       ; 0559  08
	exx                             ; 055A  d9
	call BANKCALL_I                 ; 055B  cda009
	jp nc,APORESUME                 ; 055E  d2a10c       NC: resume the interrupted program (0CA1H)
	call SIGCLR                     ; 0561  cde208       failed: clear the signature, normal start

; Normal start.
L0564:
	ld sp,0F5FFH                    ; 0564  31fff5
	call S078F                      ; 0567  cd8f07       bank 3 6AF2H: first reset-only helper
	ld hl,0F0B2H                    ; 056A  21b2f0
	ld b,06H                        ; 056D  0606
L056F:
	ld (hl),00H                     ; 056F  3600
