; Modified registers: A = bank; BC preserved
;   Error conditions: None
;------------------------------------------------------------------------------
BANKREAD_I:
	push bc                         ; 0B15  c5
	inc b                           ; 0B16  04
	in a,(P_BANK)                   ; 0B17  db31
	dec b                           ; 0B19  05
	jr z,L0B29                      ; 0B1A  280d
	rrca                            ; 0B1C  0f
	dec b                           ; 0B1D  05
	jr z,L0B2D                      ; 0B1E  280d
	rrca                            ; 0B20  0f
	rrca                            ; 0B21  0f
	rrca                            ; 0B22  0f
	dec b                           ; 0B23  05
	jr z,L0B2D                      ; 0B24  2807
	rrca                            ; 0B26  0f
	rrca                            ; 0B27  0f
	rrca                            ; 0B28  0f
L0B29:
	and 01H                         ; 0B29  e601
	jr L0B2F                        ; 0B2B  1802
L0B2D:
	and 07H                         ; 0B2D  e607
L0B2F:
