;------------------------------------------------------------------------------
; 0B31H - (0196H) Map slot 1b also at 4000H-7FFFH of bank 1 (SLOT1MAP)
; Sets SLOTMAP b2; port 3CH is written with all interrupts masked.
;
;   Entry parameters: A = 0 normal, else slot 1b mapped
; Modified registers: A; BC preserved
;   Error conditions: None
;------------------------------------------------------------------------------
SLOT1MAP_I:
	push bc                         ; 0B31  c5
	ld b,a                          ; 0B32  47
	in a,(P_ZMSK)                   ; 0B33  db35
	ld c,a                          ; 0B35  4f
	xor a                           ; 0B36  af
	out (P_ZMSK),a                  ; 0B37  d335
	ld a,b                          ; 0B39  78
	ld b,00H                        ; 0B3A  0600
	and a                           ; 0B3C  a7
	jr z,L0B41                      ; 0B3D  2802
	ld b,04H                        ; 0B3F  0604
L0B41:
	ld a,(SLOTMAPM)                 ; 0B41  3a8df0
	and 0FBH                        ; 0B44  e6fb
	or b                            ; 0B46  b0
	ld (SLOTMAPM),a                 ; 0B47  328df0
	out (P_SLOT),a                  ; 0B4A  d33c
	ld a,c                          ; 0B4C  79
	out (P_ZMSK),a                  ; 0B4D  d335
	pop bc                          ; 0B4F  c1
