SLOT2MAP_I:
	push bc                         ; 0B51  c5
	ld b,a                          ; 0B52  47
	in a,(P_ZMSK)                   ; 0B53  db35
	ld c,a                          ; 0B55  4f
	xor a                           ; 0B56  af
	out (P_ZMSK),a                  ; 0B57  d335
	ld a,b                          ; 0B59  78
	ld b,00H                        ; 0B5A  0600
	and a                           ; 0B5C  a7
	jr z,L0B66                      ; 0B5D  2807
	ld b,20H                        ; 0B5F  0620
	dec a                           ; 0B61  3d
	jr z,L0B66                      ; 0B62  2802
	ld b,10H                        ; 0B64  0610
L0B66:
	ld a,(SLOTMAPM)                 ; 0B66  3a8df0
	and 0CFH                        ; 0B69  e6cf
	or b                            ; 0B6B  b0
	ld (SLOTMAPM),a                 ; 0B6C  328df0
	out (P_SLOT),a                  ; 0B6F  d33c
