;------------------------------------------------------------------------------
; 0B76H - Jump into another bank and back (BANKJP, RST 18H)
; Called as  RST 18H / DW target.  The bank follows from the target:
;   0000H-3FFFH -> pages 0 and 1 = bank 0      4000H-7FFFH -> page 1 = bank 3
;   8000H-BFFFH -> page 2 = bank 6             C000H-FFFFH -> page 1 = bank 0,
;                                              address - 8000H
; Port 3DH := 04H.  The return slot that pointed at the operand is replaced
; by the saved port 31H / 3DH values and BJPRET is pushed as the target's
; return address, so the target returns straight to the caller of the jump-
; table entry with the banking restored.
;
;       Inline bytes: DW target
; Modified registers: None: all registers pass through to the target and back
;   Error conditions: None
;------------------------------------------------------------------------------
BANKJP_I:
	push hl                         ; 0B76  e5
	push hl                         ; 0B77  e5
	push af                         ; 0B78  f5
	push de                         ; 0B79  d5
	ld hl,0009H                     ; 0B7A  210900       SP+9 -> high byte of the operand pointer
	add hl,sp                       ; 0B7D  39
	ld d,(hl)                       ; 0B7E  56           operand pointer high := old port 3DH
	ld a,(PORT3D_M)                 ; 0B7F  3a7df0
	ld (hl),a                       ; 0B82  77
	ld a,04H                        ; 0B83  3e04
	ld (PORT3D_M),a                 ; 0B85  327df0
	out (P_ROMSEL),a                ; 0B88  d33d
	dec hl                          ; 0B8A  2b
	ld e,(hl)                       ; 0B8B  5e           operand pointer low := old port 31H
	in a,(P_BANK)                   ; 0B8C  db31
	ld (hl),a                       ; 0B8E  77
	dec hl                          ; 0B8F  2b
	ld (hl),0BH                     ; 0B90  360b         plant BJPRET (0BC8H) as return address
	dec hl                          ; 0B92  2b
	ld (hl),0C8H                    ; 0B93  36c8
	ex de,hl                        ; 0B95  eb
	ld e,(hl)                       ; 0B96  5e
	inc hl                          ; 0B97  23
	ld d,(hl)                       ; 0B98  56
	ex de,hl                        ; 0B99  eb
	ld a,h                          ; 0B9A  7c
	add a,a                         ; 0B9B  87
	jr c,L0BA8                      ; 0B9C  380a
	jp m,L0BBC                      ; 0B9E  fabc0b
	in a,(P_BANK)                   ; 0BA1  db31
	and 0F0H                        ; 0BA3  e6f0
	jp L0BC2                        ; 0BA5  c3c20b
L0BA8:
	jp m,L0BB4                      ; 0BA8  fab40b
	in a,(P_BANK)                   ; 0BAB  db31
	and 8FH                         ; 0BAD  e68f
	or 60H                          ; 0BAF  f660
	jp L0BC2                        ; 0BB1  c3c20b
L0BB4:
	res 7,h                         ; 0BB4  cbbc         C000H alias: bank 0 upper half at target - 8000H
	in a,(P_BANK)                   ; 0BB6  db31
	and 0F1H                        ; 0BB8  e6f1
	jr L0BC2                        ; 0BBA  1806
L0BBC:
	in a,(P_BANK)                   ; 0BBC  db31
	and 0F1H                        ; 0BBE  e6f1
	or 06H                          ; 0BC0  f606
L0BC2:
	out (P_BANK),a                  ; 0BC2  d331
	pop de                          ; 0BC4  d1
	pop af                          ; 0BC5  f1
	ex (sp),hl                      ; 0BC6  e3           target on the stack, HL restored; RET = jump
	ret                             ; 0BC7  c9



;------------------------------------------------------------------------------
; 0BC8H - Return trampoline pushed by BANKJP (restores ports 31H/3DH)
;------------------------------------------------------------------------------
BJPRET:
	push af                         ; 0BC8  f5
	push hl                         ; 0BC9  e5
	ld hl,0004H                     ; 0BCA  210400       SP+4: saved port 31H, then port 3DH
	add hl,sp                       ; 0BCD  39
	ld a,(hl)                       ; 0BCE  7e
	out (P_BANK),a                  ; 0BCF  d331
	inc hl                          ; 0BD1  23
	ld a,(hl)                       ; 0BD2  7e
	ld (PORT3D_M),a                 ; 0BD3  327df0
	out (P_ROMSEL),a                ; 0BD6  d33d
	pop hl                          ; 0BD8  e1
	pop af                          ; 0BD9  f1
	inc sp                          ; 0BDA  33           drop the saved values, return to the original caller
	inc sp                          ; 0BDB  33
	ret                             ; 0BDC  c9



;------------------------------------------------------------------------------
; 0BDDH - (01B1H) Copy C bytes (C = 0: 256) from HL to DE with port 31H := B
;
;   Entry parameters: HL = source, DE = destination, C = count, B = port 31H
; Modified registers: HL, DE past the copy, BC = 0, A; port 31H restored
;   Error conditions: None
;------------------------------------------------------------------------------
BANKCPY_I:
	in a,(P_BANK)                   ; 0BDD  db31
	push af                         ; 0BDF  f5
	ld a,b                          ; 0BE0  78
	out (P_BANK),a                  ; 0BE1  d331
	ld b,00H                        ; 0BE3  0600
	ldir                            ; 0BE5  edb0
	pop af                          ; 0BE7  f1
	out (P_BANK),a                  ; 0BE8  d331
	ret                             ; 0BEA  c9



;------------------------------------------------------------------------------
; 0BEBH - (01EAH) Switch off (OFF key / POWER OFF)
; Nothing to resume: AAH x4 at ZZ.  The modules (A = 3) and the COM driver
; are told, then the LH-5803 OFF routine removes the power.  Refused while
; the ON key is held (port 1FH b7).
;------------------------------------------------------------------------------
POFF_I:
	di                              ; 0BEB  f3
	in a,(P_OPB)                    ; 0BEC  db1f         ON key held: no power-off now
	rla                             ; 0BEE  17
	jr nc,L0BF3                     ; 0BEF  3002
	ei                              ; 0BF1  fb
	ret                             ; 0BF2  c9
L0BF3:
	call LCDWAIT                    ; 0BF3  cdea08
	ld a,3EH                        ; 0BF6  3e3e
	out (P_LCD1C),a                 ; 0BF8  d350
	call S0820                      ; 0BFA  cd2008       bank 3 6C0BH: save the module configuration
	ld hl,ZZ                        ; 0BFD  2108fa       signature AAH x4: normal off
	ld b,04H                        ; 0C00  0604
L0C02:
	ld (hl),0AAH                    ; 0C02  36aa
	inc hl                          ; 0C04  23
	djnz L0C02                      ; 0C05  10fb
	ld a,03H                        ; 0C07  3e03         every module: function 3 (power off)
	ld de,(ROM4MAP)                 ; 0C09  ed5baef0
	ld l,02H                        ; 0C0D  2e02
	call CALLMODS                   ; 0C0F  cd3509
	ld a,03H                        ; 0C12  3e03         COM IOCS 0 with A = 3
	ld c,00H                        ; 0C14  0e00
	call COM                        ; 0C16  cdd801
	ld a,11H                        ; 0C19  3e11         11H: PCTRL power-off step (keeps the LCD clock bit)
	out (P_CGC),a                   ; 0C1B  d337
	ld a,03H                        ; 0C1D  3e03
	call PAOFF_ENT                  ; 0C1F  cdc901
	di                              ; 0C22  f3           returned (not on a real unit): restart as ON-key power-on
	ld a,10H                        ; 0C23  3e10
	out (P_CGC),a                   ; 0C25  d337
	jp RSTSAVE                      ; 0C27  c35c03



;------------------------------------------------------------------------------
; 0C2AH - (01EDH) Auto power-off with every register preserved
; Includes IX, IY and the alternate set: the program resumes after the next
; power-on.
;------------------------------------------------------------------------------
PAOFF_I:
	push af                         ; 0C2A  f5
	push bc                         ; 0C2B  c5
	push de                         ; 0C2C  d5
	push hl                         ; 0C2D  e5
	push ix                         ; 0C2E  dde5
	push iy                         ; 0C30  fde5
	ex af,af'                       ; 0C32  08
	exx                             ; 0C33  d9
	push af                         ; 0C34  f5
	push bc                         ; 0C35  c5
	push de                         ; 0C36  d5
	push hl                         ; 0C37  e5
	call APO_I                      ; 0C38  cd4a0c
	pop hl                          ; 0C3B  e1
	pop de                          ; 0C3C  d1
	pop bc                          ; 0C3D  c1
	pop af                          ; 0C3E  f1
	exx                             ; 0C3F  d9
	ex af,af'                       ; 0C40  08
	pop iy                          ; 0C41  fde1
	pop ix                          ; 0C43  dde1
	pop hl                          ; 0C45  e1
	pop de                          ; 0C46  d1
	pop bc                          ; 0C47  c1
	pop af                          ; 0C48  f1
	ret                             ; 0C49  c9



;------------------------------------------------------------------------------
; 0C4AH - (0005H) Auto power-off
; The port state (30H, 31H, 35H, SLOTMAP, 3DH) is pushed and SP saved at
; SAVESP, ZZ := A5H x4 (resume signature), modules and COM told (A = 4), then
; power off.  The reset code later reloads SP and continues at APORESUME
; (0CA1H), which returns from this routine.
;------------------------------------------------------------------------------
APO_I:
	di                              ; 0C4A  f3
	in a,(P_OPB)                    ; 0C4B  db1f
	rla                             ; 0C4D  17
	jr nc,L0C52                     ; 0C4E  3002
	ei                              ; 0C50  fb
	ret                             ; 0C51  c9
L0C52:
	call LCDWAIT                    ; 0C52  cdea08
	ld a,3EH                        ; 0C55  3e3e
	out (P_LCD1C),a                 ; 0C57  d350
	in a,(P_MOD)                    ; 0C59  db30
	ld b,a                          ; 0C5B  47
	in a,(P_BANK)                   ; 0C5C  db31
	ld c,a                          ; 0C5E  4f
	push bc                         ; 0C5F  c5
	in a,(P_ZMSK)                   ; 0C60  db35
	ld b,a                          ; 0C62  47
	ld a,(SLOTMAPM)                 ; 0C63  3a8df0
	ld c,a                          ; 0C66  4f
	push bc                         ; 0C67  c5
	ld a,(PORT3D_M)                 ; 0C68  3a7df0
	push af                         ; 0C6B  f5
	ld (SAVESP),sp                  ; 0C6C  ed73daf0
	call S0820                      ; 0C70  cd2008
	ld hl,ZZ                        ; 0C73  2108fa
	ld b,04H                        ; 0C76  0604         A5H x4: resumable
L0C78:
	ld (hl),0A5H                    ; 0C78  36a5
	inc hl                          ; 0C7A  23
	djnz L0C78                      ; 0C7B  10fb
	ld a,04H                        ; 0C7D  3e04
	ld de,(ROM4MAP)                 ; 0C7F  ed5baef0
	ld hl,4002H                     ; 0C83  210240       every module: function 4 at 4002H
	call CALLMODS                   ; 0C86  cd3509
	ld a,04H                        ; 0C89  3e04
	ld c,00H                        ; 0C8B  0e00
	call COM                        ; 0C8D  cdd801
	ld a,11H                        ; 0C90  3e11
	out (P_CGC),a                   ; 0C92  d337
	ld a,04H                        ; 0C94  3e04
	call PAOFF_ENT                  ; 0C96  cdc901
	di                              ; 0C99  f3
	ld a,10H                        ; 0C9A  3e10
	out (P_CGC),a                   ; 0C9C  d337
	jp RSTSAVE                      ; 0C9E  c35c03



;------------------------------------------------------------------------------
; 0CA1H - Resume after auto power-off
; Clears the signature, restores the ports, display on, EI, returns from APO.
;------------------------------------------------------------------------------
APORESUME:
	xor a                           ; 0CA1  af
	ld (ZZ),a                       ; 0CA2  3208fa
	pop af                          ; 0CA5  f1
	ld (PORT3D_M),a                 ; 0CA6  327df0
	out (P_ROMSEL),a                ; 0CA9  d33d
	pop bc                          ; 0CAB  c1
	ld a,c                          ; 0CAC  79
	ld (SLOTMAPM),a                 ; 0CAD  328df0
	out (P_SLOT),a                  ; 0CB0  d33c
	ld a,b                          ; 0CB2  78
	out (P_ZMSK),a                  ; 0CB3  d335
	pop bc                          ; 0CB5  c1
	ld a,c                          ; 0CB6  79
	out (P_BANK),a                  ; 0CB7  d331
	ld a,b                          ; 0CB9  78
	out (P_MOD),a                   ; 0CBA  d330
	call LCDWAIT                    ; 0CBC  cdea08
	ld a,3FH                        ; 0CBF  3e3f
	out (P_LCD1C),a                 ; 0CC1  d350
	ei                              ; 0CC3  fb
	ret                             ; 0CC4  c9



;------------------------------------------------------------------------------
; 0CC5H - Return at once (dummy hook)
;------------------------------------------------------------------------------
RETONLY2:
	ret                             ; 0CC5  c9



;------------------------------------------------------------------------------
; 0CC6H - (0235H) Read (HL) in bank C (BANKPEEK); BANKPOKE (0238H) writes A
; The bank stays selected afterwards (port 3DH := 04H).
;
;   Entry parameters: HL = address, C = bank (BANKPOKE: A = byte)
; Modified registers: A = byte (BANKPEEK); BC preserved
;   Error conditions: None
;------------------------------------------------------------------------------
BANKPEEK_I:
	push bc                         ; 0CC6  c5
	call SELBANKC                   ; 0CC7  cdd60c
	ld a,(hl)                       ; 0CCA  7e
	pop bc                          ; 0CCB  c1
	ret                             ; 0CCC  c9
BANKPOKE_I:
	push bc                         ; 0CCD  c5
	push af                         ; 0CCE  f5
	call SELBANKC                   ; 0CCF  cdd60c
	pop af                          ; 0CD2  f1
	ld (hl),a                       ; 0CD3  77
	pop bc                          ; 0CD4  c1
	ret                             ; 0CD5  c9



;------------------------------------------------------------------------------
; 0CD6H - Select bank C for the page of HL
;------------------------------------------------------------------------------
SELBANKC:
	ld a,04H                        ; 0CD6  3e04
	ld (PORT3D_M),a                 ; 0CD8  327df0
	out (P_ROMSEL),a                ; 0CDB  d33d
	ld a,c                          ; 0CDD  79
	call PAGEBITS                   ; 0CDE  cdd709
	in a,(P_BANK)                   ; 0CE1  db31
	and c                           ; 0CE3  a1
	or b                            ; 0CE4  b0
	out (P_BANK),a                  ; 0CE5  d331
	ret                             ; 0CE7  c9



; ============================================================================
; BASIC BOOT
; ============================================================================

;------------------------------------------------------------------------------
; 0CE8H - Default boot vector: BASIC cold / warm start
; BOOTBK/BOOTAD = bank 0, 0CE8H; entered by BANKJUMP from the reset code.
; Resets the display, installs the default APO handler and user interrupt
; hooks, re-checks the memory configuration and then either
;  - prints "NEW0? :CHECK xx" if the configuration changed / problems were
;    flagged in FA21H-FA24H during reset, or
;  - (WAKE$ power-on) types WAKE$(0) / WAKE$(1) into the key buffer, or
;  - (AUTO RUN) finds AUTORUN.BAS on a device or an ARUN program, or
;  - just enters BASIC command mode (RESCA).
;
;   Entry parameters: A = start cause (RSTCAUSE)
; Modified registers: Does not return
;   Error conditions: None
;------------------------------------------------------------------------------
BASBOOT:
	push af                         ; 0CE8  f5
	cp 01H                          ; 0CE9  fe01
	jr nz,L0CF2                     ; 0CEB  2005
	ld hl,TITLE                     ; 0CED  21d5f1       ALL RESET: TITLE := S0
	ld (hl),00H                     ; 0CF0  3600
L0CF2:
	cp 10H                          ; 0CF2  fe10         a reset (not a power-on): default status symbols
	call c,SYMDEFLT                 ; 0CF4  dc5310
	call EDRESET                    ; 0CF7  cd0c03
	ld de,0000H                     ; 0CFA  110000
	call CRSRSET                    ; 0CFD  cd1501
	xor a                           ; 0D00  af           26-character mode
	call LWIDTH                     ; 0D01  cd0f01
	call CLS                        ; 0D04  cd1201
	ld a,01H                        ; 0D07  3e01
	call BSPCTR                     ; 0D09  cde500
	ld a,03H                        ; 0D0C  3e03         default auto-power-on handler: bank 3, 407EH
	ld hl,407EH                     ; 0D0E  217e40
	ld (APONBK),a                   ; 0D11  32cbf0
	ld (APONAD),hl                  ; 0D14  22ccf0

; Default user hooks for the three sub-CPU timers: bank byte C0H (b7=b6=1: armed,
; bank 0) and the handlers UIWAKE/UITIME/UIALARM which just flag BINTREQ.
	ld a,0C0H                       ; 0D17  3ec0
	ld hl,UIWAKE                    ; 0D19  219610
	ld (0F0C9H),hl                  ; 0D1C  22c9f0
	ld (UHWAKE),a                   ; 0D1F  32c8f0
	ld hl,UITIME                    ; 0D22  219c10
	ld (UHALM1),a                   ; 0D25  32c2f0
	ld (0F0C3H),hl                  ; 0D28  22c3f0
	ld hl,UIALARM                   ; 0D2B  21a210
	ld (UHALM2),a                   ; 0D2E  32c5f0
	ld (0F0C6H),hl                  ; 0D31  22c6f0
	xor a                           ; 0D34  af
	ld (BINTREQ),a                  ; 0D35  3227f1

; Keep the S0 descriptor (F029H/F02AH) and S0MTB to see whether SSLOTMP
; changes them.
	ld hl,(S0DESC)                  ; 0D38  2a29f0
	ld (ZZ),hl                      ; 0D3B  2208fa
	ld a,(S0MTB)                    ; 0D3E  3a2af0
	ld (0FA0AH),a                   ; 0D41  320afa
	call SSLOTMP                    ; 0D44  cd3b00
	ld hl,BMODE                     ; 0D47  21bcf1
	bit 6,(hl)                      ; 0D4A  cb76         BMODE.6: MODE 1 (PC-1500 mode) active?
	jr z,L0D56                      ; 0D4C  2808
	ld a,01H                        ; 0D4E  3e01
	call RAMODSET_I                 ; 0D50  cd2317       keep it if bank 3 1500 mode accepts (A = 0)
	and a                           ; 0D53  a7
	jr z,L0D5B                      ; 0D54  2805
L0D56:
	res 6,(hl)                      ; 0D56  cbb6
	call PRGMODSEL                  ; 0D58  cd0810
L0D5B:
	ld hl,(ZZ)                      ; 0D5B  2a08fa
	ld de,(S0DESC)                  ; 0D5E  ed5b29f0
	and a                           ; 0D62  a7
	sbc hl,de                       ; 0D63  ed52
	jr nz,L0D71                     ; 0D65  200a
	ld a,(0FA0AH)                   ; 0D67  3a0afa
	ld b,a                          ; 0D6A  47
	ld a,(S0MTB)                    ; 0D6B  3a2af0
	cp b                            ; 0D6E  b8
	jr z,L0D76                      ; 0D6F  2805
L0D71:
	ld hl,0FA23H                    ; 0D71  2123fa       S0 layout changed -> "NEW0?"
	set 7,(hl)                      ; 0D74  cbfe
L0D76:
	call SETPRSLOT                  ; 0D76  cd3e00       set F050H-F05BH (write-protect/RAM-only areas)
	pop af                          ; 0D79  f1
	push af                         ; 0D7A  f5
	cp 01H                          ; 0D7B  fe01         ALL RESET: clear all program memory, then SYSRESET
	call z,CLRPRGMEM                ; 0D7D  ccad0f

; Anything flagged during the reset (FA21H-FA24H)?  Then build the message
; "NEW0? :CHECK xx" at FB10H ("CHECK " without the colon when there is no
; "NEW0?"; "NEW0?" only when FA23H.7, memory configuration changed).
	ld hl,0FA21H                    ; 0D80  2121fa
	ld a,(hl)                       ; 0D83  7e
	inc hl                          ; 0D84  23
	or (hl)                         ; 0D85  b6
	inc hl                          ; 0D86  23
	inc hl                          ; 0D87  23
	or (hl)                         ; 0D88  b6
	ld b,a                          ; 0D89  47
	dec hl                          ; 0D8A  2b
	or (hl)                         ; 0D8B  b6
	jp z,L0E45                      ; 0D8C  ca450e
	pop de                          ; 0D8F  d1
	ld de,0FB10H                    ; 0D90  1110fb
	bit 7,(hl)                      ; 0D93  cb7e
	jr z,L0DA1                      ; 0D95  280a
	ld a,b                          ; 0D97  78
	ld hl,0E24H                     ; 0D98  21240e
	ld bc,0006H                     ; 0D9B  010600
	ldir                            ; 0D9E  edb0
	ld b,a                          ; 0DA0  47
